      SUBROUTINE RCTORSCC     TRANSFERS MATRIX RC TO RSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'TC.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'UC.CIN'      INCLUDE 'US.CIN'      INTEGER         JK, JKM, JKLMCC------------------------------------------------------------------------C      DO 10 JK = 1, 36   10 RSL(JK) = RCL(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TSL(JKM) = TCL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   USL(JKLM) = UCL(JKLM)      ENDIF      RETURN      END